INSERT INTO exercises (slug, name, description, default_dose, equipment, tags) VALUES ('catcow', 'Cat-cow', 'On hands and knees. Arch your back and lift your chest and tailbone, then round your spine and tuck your chin. Move with your breathing.', '10 reps', '[]', '[]') ON CONFLICT(slug) DO UPDATE SET name = excluded.name, description = excluded.description, default_dose = excluded.default_dose;
INSERT INTO exercises (slug, name, description, default_dose, equipment, tags) VALUES ('bridge', 'Glute bridge', 'Lie on your back, knees bent, feet flat and hip-width apart. Push through your heels to lift your hips until shoulders, hips and knees form a straight line. Squeeze your glutes at the top and lower slowly.', '10 reps', '[]', '[]') ON CONFLICT(slug) DO UPDATE SET name = excluded.name, description = excluded.description, default_dose = excluded.default_dose;
INSERT INTO exercises (slug, name, description, default_dose, equipment, tags) VALUES ('squat', 'Bodyweight squat', 'Feet shoulder-width apart. Sit your hips back and down, keeping your chest up and knees tracking over your toes. Stand tall.', '10 reps', '[]', '[]') ON CONFLICT(slug) DO UPDATE SET name = excluded.name, description = excluded.description, default_dose = excluded.default_dose;
INSERT INTO exercises (slug, name, description, default_dose, equipment, tags) VALUES ('inchworm', 'Inchworm', 'Stand, then hinge forward and walk your hands out to a high plank. Pause, walk your feet toward your hands, then stand back up.', '5 reps', '[]', '[]') ON CONFLICT(slug) DO UPDATE SET name = excluded.name, description = excluded.description, default_dose = excluded.default_dose;
INSERT INTO exercises (slug, name, description, default_dose, equipment, tags) VALUES ('goblet', 'Goblet squat', 'Hold the bell at your chest by the horns, elbows tucked in. Squat as deep as you can with your chest tall, then drive up through your heels.', '45 sec', '[]', '[]') ON CONFLICT(slug) DO UPDATE SET name = excluded.name, description = excluded.description, default_dose = excluded.default_dose;
INSERT INTO exercises (slug, name, description, default_dose, equipment, tags) VALUES ('row', 'Bent-over row', 'Hinge at the hips with a flat back, bell in one hand and free hand on your thigh. Pull the bell to your hip, squeezing your shoulder blade, then lower under control. Switch arms halfway.', '45 sec', '[]', '[]') ON CONFLICT(slug) DO UPDATE SET name = excluded.name, description = excluded.description, default_dose = excluded.default_dose;
INSERT INTO exercises (slug, name, description, default_dose, equipment, tags) VALUES ('rdl', 'Romanian deadlift', 'Hold the bell in front of your thighs with soft knees. Push your hips back and slide the bell down your legs until you feel a hamstring stretch, back flat. Drive your hips forward to stand.', '45 sec', '[]', '[]') ON CONFLICT(slug) DO UPDATE SET name = excluded.name, description = excluded.description, default_dose = excluded.default_dose;
INSERT INTO exercises (slug, name, description, default_dose, equipment, tags) VALUES ('press', 'Floor press or overhead press', 'Floor press: lie on your back, knees bent, elbow resting on the floor, and press the bell straight up. Overhead press: stand, and press from shoulder to overhead with ribs down. Switch arms halfway.', '45 sec', '[]', '[]') ON CONFLICT(slug) DO UPDATE SET name = excluded.name, description = excluded.description, default_dose = excluded.default_dose;
INSERT INTO exercises (slug, name, description, default_dose, equipment, tags) VALUES ('swing', 'Kettlebell swing', 'Feet wider than shoulders, bell on the floor just ahead of you. Hinge, hike the bell back between your legs, then snap your hips forward to float it to chest height. The power comes from your hips, not your arms.', '20 reps', '[]', '[]') ON CONFLICT(slug) DO UPDATE SET name = excluded.name, description = excluded.description, default_dose = excluded.default_dose;
INSERT INTO exercises (slug, name, description, default_dose, equipment, tags) VALUES ('lunge', 'Reverse lunge', 'Hold the bell at your chest. Step one foot back and lower until the back knee nearly touches the floor, front shin vertical. Push through the front heel to return, then switch legs.', '10 reps (5 per leg)', '[]', '[]') ON CONFLICT(slug) DO UPDATE SET name = excluded.name, description = excluded.description, default_dose = excluded.default_dose;
INSERT INTO exercises (slug, name, description, default_dose, equipment, tags) VALUES ('pushup', 'Push-up', 'Hands under shoulders, body in one straight line. Lower your chest toward the floor, then press back up. Drop to your knees if you need to.', '5 reps', '[]', '[]') ON CONFLICT(slug) DO UPDATE SET name = excluded.name, description = excluded.description, default_dose = excluded.default_dose;
INSERT INTO exercises (slug, name, description, default_dose, equipment, tags) VALUES ('plank', 'Plank', 'Forearms on the mat, elbows under your shoulders. Make a straight line from head to heels, brace your abs and squeeze your glutes.', '30 sec', '[]', '[]') ON CONFLICT(slug) DO UPDATE SET name = excluded.name, description = excluded.description, default_dose = excluded.default_dose;
INSERT INTO exercises (slug, name, description, default_dose, equipment, tags) VALUES ('twist', 'Russian twist', 'Sit with knees bent and lean back slightly, holding the bell at your chest. Rotate side to side, tapping the bell down beside each hip. Lift your feet to make it harder.', '30 sec', '[]', '[]') ON CONFLICT(slug) DO UPDATE SET name = excluded.name, description = excluded.description, default_dose = excluded.default_dose;
INSERT INTO exercises (slug, name, description, default_dose, equipment, tags) VALUES ('deadbug', 'Dead bug', 'Lie on your back with arms pointing to the ceiling and knees bent over your hips. Lower your opposite arm and leg toward the floor, keeping your lower back pressed into the mat. Return and alternate.', '30 sec', '[]', '[]') ON CONFLICT(slug) DO UPDATE SET name = excluded.name, description = excluded.description, default_dose = excluded.default_dose;
INSERT INTO exercises (slug, name, description, default_dose, equipment, tags) VALUES ('sideplank', 'Side plank', 'On one forearm with feet stacked, lift your hips so your body forms a straight line. Keep your hips high and hold.', '15 sec per side', '[]', '[]') ON CONFLICT(slug) DO UPDATE SET name = excluded.name, description = excluded.description, default_dose = excluded.default_dose;
INSERT INTO exercises (slug, name, description, default_dose, equipment, tags) VALUES ('child', 'Child''s pose', 'Kneel and sit your hips back toward your heels, arms extended in front and forehead resting down. Let your back and shoulders relax.', '45 sec', '[]', '[]') ON CONFLICT(slug) DO UPDATE SET name = excluded.name, description = excluded.description, default_dose = excluded.default_dose;
INSERT INTO exercises (slug, name, description, default_dose, equipment, tags) VALUES ('hipflex', 'Hip flexor stretch', 'Half-kneeling with your back knee on the mat. Tuck your pelvis under and shift forward until you feel a stretch across the front of your back hip.', '30 sec per side', '[]', '[]') ON CONFLICT(slug) DO UPDATE SET name = excluded.name, description = excluded.description, default_dose = excluded.default_dose;
INSERT INTO exercises (slug, name, description, default_dose, equipment, tags) VALUES ('hamstring', 'Hamstring stretch', 'Sit or lie with one leg extended, then hinge forward from the hips (or raise the leg on your back), keeping the back long.', '30 sec per side', '[]', '[]') ON CONFLICT(slug) DO UPDATE SET name = excluded.name, description = excluded.description, default_dose = excluded.default_dose;
INSERT INTO exercises (slug, name, description, default_dose, equipment, tags) VALUES ('fig4', 'Figure-4 glute stretch', 'Lie on your back and cross one ankle over the opposite knee. Pull the bottom thigh toward your chest until you feel a stretch in the glute.', '30 sec per side', '[]', '[]') ON CONFLICT(slug) DO UPDATE SET name = excluded.name, description = excluded.description, default_dose = excluded.default_dose;
INSERT INTO exercises (slug, name, description, default_dose, equipment, tags) VALUES ('shoulder', 'Cross-body shoulder stretch', 'Draw one arm across your chest and hold it with the other. Keep your shoulders relaxed and away from your ears.', '30 sec per side', '[]', '[]') ON CONFLICT(slug) DO UPDATE SET name = excluded.name, description = excluded.description, default_dose = excluded.default_dose;
INSERT INTO workouts (id, owner_user_id, organization_id, name, description, is_template, created_at, updated_at) VALUES ('kettlebell-and-mat', NULL, NULL, 'Kettlebell and mat', '30 minutes of strength, endurance and core. You need a mat and a kettlebell, ideally one heavier and one lighter.', 1, unixepoch(), unixepoch()) ON CONFLICT(id) DO UPDATE SET name = excluded.name, description = excluded.description, updated_at = unixepoch();
